API Gateway / Ingress Controller.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway_boundary, "API Gateway / Ingress Controller") {
    Component(Traffic_Splitter_and_Router, "Traffic Splitter and Router", "Azure Application Gateway / NGINX", "Handles dynamic traffic splitting between the modern cloud application and the legacy mainframe system.")
    Component(Circuit_Breaker, "Circuit Breaker", "NGINX / Envoy", "Protects downstream services and manages failures during legacy mainframe communications.")
    Component(Edge_JWT_Validator, "Edge JWT Validator", "Azure Active Directory SSO / OAuth2", "Validates JSON Web Tokens at the edge and enforces security policies.")
}

Rel(Edge_JWT_Validator, Traffic_Splitter_and_Router, "Authenticates incoming requests before routing")
Rel(Traffic_Splitter_and_Router, Circuit_Breaker, "Routes filtered traffic through")

@enduml

Azure Cache / Local Caching Layer.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Azure Cache / Local Caching Layer container

Container_Boundary(azure_cache_container, "Azure Cache / Local Caching Layer") {
    Component(redis_client, "Redis Cache Client", "StackExchange.Redis", "Manages TCP connections, serialization, and communication with Azure Cache for Redis.")
    Component(cache_manager, "Cache Manager", "C# / .NET Memory Management", "Encapsulates caching logic, expiration policies, and fallback strategies for claims data.")
}

Rel(cache_manager, redis_client, "Invokes read and write operations", "Function Call")

@enduml

Business/Migration Analytics Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Business/Migration Analytics Container", "Business/Migration Analytics Container") {
    Component(DashboardUI_Service, "Dashboard UI Service", "Python, Azure Analytics", "Serves migration dashboards and financial risk reports to Business Operations Managers and Migration Leads.")
    Component(MigrationTelemetry_IngestionEngine, "Migration Telemetry Ingestion Engine", "Python", "Ingests event streams from Azure Service Bus to process migration telemetry without direct mainframe polling.")
    Component(DryRunSimulation_AnalyticsProcessor, "Dry-Run Simulation & Analytics Processor", "Python", "Processes data for migration velocity, zero-loss reconciliation, rollback readiness, and dry-run simulation results.")
}

Rel(DashboardUI_Service, MigrationTelemetry_IngestionEngine, "Queries processed migration metrics")
Rel(MigrationTelemetry_IngestionEngine, DryRunSimulation_AnalyticsProcessor, "Passes ingested event streams for analysis")

@enduml
